pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Setup: deployer is owner and rewardDistributor
        address user = address(0x123);
        address rewardToken = address(0x456);

        // Mint staking tokens to user
        deal(address(c.stakingToken()), user, 100 ether);

        // User stakes
        vm.prank(user);
        c.stake(10 ether);

        // Owner adds reward token
        c.addReward(rewardToken);

        // Fund reward distributor and notify reward
        deal(rewardToken, address(this), 1000 ether);
        // Use IERC20 approve and then notifyRewardAmount
        // First approve the contract to spend reward tokens
        // Use low-level call since rewardToken is a separate contract that needs approval
        // In test we can treat rewardToken as a dummy, but we need actual tokens
        // For simplicity, we'll mock the reward token by dealing to the contract directly via transfer
        // Actually, we need to use a real ERC20 token. Let's use a simpler approach: 
        // set c.rewardDistributor to user? No, must remain owner's control.
        // We'll deal rewardToken to this contract, then call notifyRewardAmount.
        // But require ERC20 approval. We'll skip for now and just test the claimableRewards after addReward.
        // Actually, the bug manifests in _getReward: after getReward, claimableRewards remains >0 in bug.
        // We need to first earn rewards. Let's warp time so that rewards accrue.

        // Simpler: directly set claimableRewards via internal? No, we can't.
        // We need to add reward and let time pass so user earns.
        // Let's do full sequence: addReward, notifyRewardAmount, warp, getRewards.
        // The bug is that claimableRewards[user][rewardToken] is not reset to 0 after transfer.
        // So after getRewards, in the reference it is 0, in bug it is still the earned amount.

        // Add reward
        c.addReward(rewardToken);

        // Deploy a simple ERC20 for rewardToken (we can use address(this) as token? No, it's an address constant)
        // Use vm.mockCall to simulate token? Not allowed.
        // We'll use a different approach: use the actual token address from deployment.
        // Since we don't have a real token, we can't call safeTransfer. This won't work.
        // Let's redesign: the test must be self-contained with actual ERC20 contracts.
        // But we cannot import ERC20. We'll deploy a minimal one in setup.
        // Actually, the contract expects a token address. We'll deploy a simple ERC20 in setUp.
        // But the file shape is fixed. Let's use existing stakingToken as rewardToken? No, that's token.
        // We'll use address(this) as rewardToken and mock the calls? Not allowed.
        // The simplest: set rewardToken = address(c.stakingToken()) then use that.

        // Let's use the staking token as reward token to avoid extra contract.
        address rewardAddr = address(c.stakingToken());
        c.addReward(rewardAddr);

        // Fund this contract with reward tokens (it's also the staking token)
        // But stakingToken is a real ERC20; we need to mint. Use deal.
        deal(rewardAddr, address(this), 1000 ether);

        // Approve spending
        // We need IERC20 interface. Use vm.prank and call approve on the token.
        // But we don't have the interface imported. Use low-level call.
        (bool success, ) = rewardAddr.call(abi.encodeWithSignature("approve(address,uint256)", address(c), 1000 ether));
        require(success, "approve failed");

        // Notify reward
        c.notifyRewardAmount(rewardAddr, 1000 ether);

        // Warp to let rewards accrue
        vm.warp(block.timestamp + 1 days);

        // Get rewards for user
        vm.prank(user);
        c.getRewards(user);

        // Now check claimableRewards
        uint256 claimable = c.claimableRewards(user, rewardAddr);
        // In the reference, this should be 0; in the bug, it remains positive.
        assertTrue(claimable == 0, "claimableRewards should be zero after reward collection");
    }
}

